 X("T.parse_tx(%r)['witness']" % ALICE, [['cf5efe2d8ef13ed0af21d4f4cb82422d6252d70324f6f4576b727b7d918e521c00b51be739df2f899c49dc267c0ad280aca6dab0d2fa2b42a45182fc83e81713' + '01']]),
