 X("C.ev_json('mempool_tx_466200308696215b_v1_0_0.json')['vin'][0]['witness']", ['cf5efe2d8ef13ed0af21d4f4cb82422d6252d70324f6f4576b727b7d918e521c00b51be739df2f899c49dc267c0ad280aca6dab0d2fa2b42a45182fc83e8171301']),
